mapper.select:
select c.id, c.name, c.room, c.begin_date, c.end_date, c.master_id, c.create_time, c.update_time, e.name masterName, case when now() < c.begin_date then '未开班' when now() > c.end_date then '已结课' else '已开班' end as status from clazz c left join emp e on c.master_id = e.id
and c.name like concat('%', #{name}, '%')
and c.end_date >= #{begin}
and c.end_date <= #{end}
order by c.update_time desc
